css:
[data-bz-section="location-panels"] .bz-block { padding-block: 0 }
[data-bz-section="location-panels"] .bz-block + .bz-block { padding-block-start: 0 }
/* Handoff .panel: two bordered panels, 28px apart, 36px / 32px in. */
[data-bz-section="location-panels"] .bz-row[data-bz-node="lp-grid"] { gap: 28px }
[data-bz-section="location-panels"] .bz-col[data-bz-node^="lp-card-"] { border: 1px solid var(--line); background: var(--card); padding: 36px 32px }
[data-bz-section="location-panels"] [data-bz-node^="lp-card-h"] .bz-eyebrow { font-size: 10px; line-height: 1; letter-spacing: .14em; color: var(--accent); margin: 0 0 12px }
[data-bz-section="location-panels"] [data-bz-node^="lp-card-h"] h2 { font-size: 24px; line-height: 1.7; font-weight: 800; margin: 0 0 18px }
[data-bz-section="location-panels"] [data-bz-node^="lp-card-b"] p, [data-bz-section="location-panels"] [data-bz-node^="lp-card-c-"] p { font-size: 15px; line-height: 1.7; color: var(--body-text); margin: 0 0 18px }
[data-bz-section="location-panels"] [data-bz-node^="lp-card-c-"] a { color: var(--accent); font-weight: 400; text-decoration: none }
[data-bz-section="location-panels"] [data-bz-node^="lp-card-c-"] a:hover { text-decoration: underline }
[data-bz-section="location-panels"] .bz-btns { margin-block: 0; gap: 26px; flex-wrap: wrap }
[data-bz-section="location-panels"] .bz-btn--link { font: 700 15px / 1.7 var(--font-body); color: var(--accent); text-transform: none; letter-spacing: 0 }
@media (max-width: 640px) { [data-bz-section="location-panels"] .bz-col[data-bz-node^="lp-card-"] { padding: 28px 22px } }
